#world{position:absolute;inset:0;transform-origin:960px 540px}
#fx{position:absolute;inset:0;pointer-events:none}
.sc{position:absolute;inset:0;overflow:hidden;display:none}
.e{position:absolute;left:0;top:0;white-space:nowrap}
.mono{font-family:'SFM','PingFang SC',monospace}
.tag{font:400 22px 'SFM','PingFang SC',monospace;color:var(--g1);letter-spacing:.5px}
.acc{color:var(--blue)}
.h1{font-size:108px;font-weight:600;letter-spacing:-1.5px;line-height:1.12}
.h2{font-size:88px;font-weight:600;letter-spacing:-1px;line-height:1.15}
.h3{font-size:56px;font-weight:600;letter-spacing:-.5px}
.grid{position:absolute;inset:-240px;background-image:linear-gradient(var(--line) 1px,transparent 1px),linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:240px 240px;opacity:.6}
