.pill{display:inline-block;padding:8px 22px;border-radius:40px;font:500 26px -apple-system,'PingFang SC',sans-serif}
.term{background:#0E0E0E;border-radius:16px;padding:26px 30px;font:400 26px 'SFM','PingFang SC',monospace;color:#bbb;line-height:1.7}
.hl{background:var(--blue);color:#fff;border-radius:18px;padding:0 18px}



